/* ---------- MARKET (per-business research: size, players, competitors, money map, growth) ---------- */
function mBars(rows){
  const max=Math.max.apply(null,rows.map(r=>r.v))||1;
  return `<div class="mbars">`+rows.map(r=>`<div class="mbar"><div class="mbl">${esc(r.l)}</div><div class="mbt"><div class="mbf" style="width:${Math.max(4,Math.round(r.v/max*100))}%"></div></div><div class="mbv">${esc(r.n)}</div></div>`).join("")+`</div>`;
}
function mDonut(rows){
  const colors=["#1B2A4E","#8BC34A","#0099E5","#e0a800","#c0392b","#6b7280","#9b59b6"];
  let acc=0;const R=54,C=2*Math.PI*R;
  const segs=rows.map((r,i)=>{const frac=r.v/100,len=frac*C,dash=len+" "+(C-len),off=-acc*C;acc+=frac;return `<circle r="${R}" cx="70" cy="70" fill="none" stroke="${colors[i%colors.length]}" stroke-width="22" stroke-dasharray="${dash}" stroke-dashoffset="${off}" transform="rotate(-90 70 70)"></circle>`;}).join("");
  const legend=rows.map((r,i)=>`<div class="lg"><span class="sw" style="background:${colors[i%colors.length]}"></span>${esc(r.l)} — ${r.v}%</div>`).join("");
  return `<div class="mdonut"><svg viewBox="0 0 140 140" width="140" height="140" style="flex:0 0 auto">${segs}</svg><div class="mlg">${legend}</div></div>`;
}
function mSrc(arr){return `<div class="msrc">Sources: `+arr.map(s=>`<a href="https://${esc(s.u)}" target="_blank" rel="noopener">${esc(s.t)}</a>`).join(" · ")+`</div>`;}
function mComp(c){
  let h=`<div class="mcard"><div class="mt">${esc(c.name)}${c.tag?`<span class="mtag">${esc(c.tag)}</span>`:""}</div>`;
  if(c.url)h+=`<div class="mu"><a href="https://${esc(c.url)}" target="_blank" rel="noopener">${esc(c.url)}</a></div>`;
  const f=[];
  if(c.where)f.push(["Where",c.where]);if(c.services)f.push(["Services",c.services]);
  if(c.pricing)f.push(["Pricing",c.pricing]);if(c.reviews)f.push(["Reviews",c.reviews]);
  if(c.years)f.push(["In business",c.years]);if(c.size)f.push(["Est. size",c.size]);
  if(c.rev)f.push(["Revenue",c.rev]);if(c.model)f.push(["What's different",c.model]);
  if(c.note)f.push(["Takeaway",c.note]);
  h+=`<div style="font-size:12.5px;margin-top:5px;line-height:1.5">`+f.map(x=>`<div><b>${x[0]}:</b> ${esc(x[1])}</div>`).join("")+`</div></div>`;
  return h;
}
function mStream(s){
  return `<div class="mcard"><div class="mt">${esc(s.name)}${s.inIt?`<span class="mtag">we do this</span>`:`<span class="mtag gap">add this</span>`}</div>
    <div style="font-size:12.5px;margin-top:4px;line-height:1.5"><div><b>Customer:</b> ${esc(s.who)}</div><div><b>Typical ticket:</b> ${esc(s.ticket)}</div><div><b>Frequency:</b> ${esc(s.freq)}</div><div><b>Lifetime value:</b> ${esc(s.ltv)}</div>${s.note?`<div style="margin-top:3px;color:var(--muted)">${esc(s.note)}</div>`:""}</div></div>`;
}
function mLever(l){
  return `<div class="mcard"><div class="mt">${esc(l.name)}</div>
    <div style="font-size:12.5px;margin-top:4px;line-height:1.5"><div><b>Investment:</b> ${esc(l.invest)}</div><div><b>Time horizon:</b> ${esc(l.horizon)}</div><div><b>Failure mode:</b> ${esc(l.fail)}</div>${l.caseStudy?`<div style="margin-top:4px"><b>Real example:</b> ${esc(l.caseStudy)}</div>`:""}</div></div>`;
}
function mSect(t,sub){return `<div class="secthd"><h2>${t}</h2></div>`+(sub?`<p class="muted" style="margin:0 4px 4px">${esc(sub)}</p>`:"");}
function mAcc(title,body,open){return `<details class="macc"${open?" open":""}><summary>${esc(title)}</summary><div class="maccb">${body}</div></details>`;}
function mCallout(type,title,body){return `<div class="cal ${type||""}"><b class="h">${esc(title)}</b>${esc(body)}</div>`;}
function mTimeline(){return `<div class="tline"><div class="seg" style="background:var(--accent);color:var(--accent-ink)">0-30 days</div><div class="seg" style="background:var(--brand)">31-60 days</div><div class="seg" style="background:#0070b8">61-90 days</div></div>`;}
function mCompTable(rows){return `<div style="overflow-x:auto"><table class="otable"><thead><tr><th>Competitor</th><th>Where</th><th>Size / revenue</th><th>Your edge</th></tr></thead><tbody>`+rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.where||"—")}</td><td>${esc(c.size||c.rev||"—")}</td><td>${esc(c.note||"")}</td></tr>`).join("")+`</tbody></table></div>`;}
function mIndustry(ind){
  let h=`<div class="card" style="border-left:5px solid var(--accent)"><div class="nm" style="font-size:16px">${esc(ind.name)}</div><div class="sub">${esc(ind.tag||"")}</div></div>`;
  if(ind.kpis)h+=`<div class="card"><div class="kpi">`+ind.kpis.map(k=>`<div class="k"><div class="kn">${esc(k.n)}</div><div class="kl">${esc(k.l)}</div></div>`).join("")+`</div><div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55;margin-top:8px">${esc(ind.size)}</div></div>`;
  if(ind.chart)h+=`<div class="card"><strong>${esc(ind.chart.title)}</strong>`+(ind.chart.type==="donut"?mDonut(ind.chart.rows):mBars(ind.chart.rows))+(ind.chart.note?`<div class="sub">${esc(ind.chart.note)}</div>`:"")+`</div>`;
  h+=`<div class="secthd"><h2>Who owns this pie</h2></div><div class="card">`+ind.players.map(p=>`<div class="li"><div class="grow"><div class="nm">${esc(p.name)}</div><div class="sub">${esc(p.note)}</div></div></div>`).join("")+`</div>`;
  if(ind.note)h+=`<div class="card" style="border-left:4px solid var(--accent)"><div style="font-size:13px;line-height:1.5"><b>What it means for you:</b> ${esc(ind.note)}</div></div>`;
  if(ind.sources)h+=`<div class="card">`+mSrc(ind.sources)+`</div>`;
  return h;
}
function mReport(r){
  if(!r)return `<div class="empty" style="padding:16px">No report yet.</div>`;
  let h=`<div class="card"><div class="nm" style="font-size:16px">${esc(r.name)}</div><div class="sub">${esc(r.tagline)}</div></div>`;
  if(r.kpis&&r.kpis.length>=2)h+=`<div class="tldr"><div class="t"><div class="v">${esc(r.kpis[0].n)}</div><div class="k">${esc(r.kpis[0].l)}</div></div><div class="t"><div class="v">${esc(r.kpis[1].n)}</div><div class="k">${esc(r.kpis[1].l)}</div></div><div class="t"><div class="v">${esc(r.kpis[r.kpis.length-1].n)}</div><div class="k">${esc(r.kpis[r.kpis.length-1].l)}</div></div></div>`;
  if(r.tldr){h+=mCallout("","Top recommendation",r.tldr.rec);h+=mCallout("warn","Riskiest assumption",r.tldr.risk);}
  h+=`<button class="xlink" onclick="mktView('plan')">🎯 Jump to the 12-month action plan →</button>`;
  let size=`<div class="kpi">`+r.kpis.map(k=>`<div class="k"><div class="kn">${esc(k.n)}</div><div class="kl">${esc(k.l)}</div></div>`).join("")+`</div><div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55;margin-top:8px">${esc(r.sizeText)}</div>`+(r.sizeSrc?mSrc(r.sizeSrc):"");
  if(r.share)size+=`<div style="margin-top:12px"><strong>${esc(r.share.title)}</strong>`+(r.share.type==="donut"?mDonut(r.share.rows):mBars(r.share.rows))+(r.share.note?`<div class="sub">${esc(r.share.note)}</div>`:"")+`</div>`;
  h+=mAcc("Market size — how big is the pie",size,true);
  h+=mAcc("The players — who owns the pie",(r.concentration?`<p class="muted" style="margin:0 0 8px">${esc(r.concentration)}</p>`:"")+r.players.map(p=>`<div class="li"><div class="grow"><div class="nm">${esc(p.name)}</div><div class="sub">${esc(p.note)}</div></div></div>`).join(""),false);
  h+=mAcc(`Local competitors (${r.localComps.length}) — who you're up against`,(r.localNote?`<p class="muted" style="margin:0 0 6px">${esc(r.localNote)}</p>`:"")+`<strong style="font-size:12px">Side-by-side</strong>`+mCompTable(r.localComps)+`<div class="sub" style="margin:8px 0 4px">Full profiles below.</div>`+r.localComps.map(mComp).join(""),false);
  h+=mAcc(`Comparable companies (${r.comparables.length}) — templates to grow into`,(r.compNote?`<p class="muted" style="margin:0 0 6px">${esc(r.compNote)}</p>`:"")+`<strong style="font-size:12px">Side-by-side</strong>`+mCompTable(r.comparables)+`<div class="sub" style="margin:8px 0 4px">Full profiles below.</div>`+r.comparables.map(mComp).join(""),false);
  h+=mAcc(`How money comes in (${r.streams.length} streams)`,r.streams.map(mStream).join(""),false);
  h+=mAcc(`How it grows (${r.levers.length} levers)`,r.levers.map(mLever).join(""),false);
  h+=mAcc("Revenue examples — real-size operators",r.examples.map(e=>`<div class="mcard"><div class="mt">${esc(e.tier)} <span class="mu" style="color:var(--brand);font-weight:800">${esc(e.rev)}</span></div><div style="font-size:13px;margin-top:4px;white-space:pre-wrap;line-height:1.5">${esc(e.detail)}</div></div>`).join(""),false);
  if(r.sources)h+=mAcc("All sources",mSrc(r.sources),false);
  return h;
}
