function mExpansion(){
  let h=`<div class="card"><div class="nm" style="font-size:16px">Expansion — where the businesses overlap & what's wide open</div><div class="sub">The unfair advantage is that you own two businesses that feed each other, plus a tech skill set that opens adjacent markets.</div></div>`;
  h+=mSect("Where one business feeds the other");
  const feeds=[
   {name:"Home watch -> everything",note:"Home watch makes you the trusted person at an absentee-owned property. That trust is the cheapest path to selling washing, junk, gutters AND Jamieson locks/wifi/cameras. It is the keystone — push it hardest."},
   {name:"OBX Lot Solutions -> Jamieson tech",note:"Every washing/home-watch customer is a warm Jamieson lead. 'While we're out, did you know we also do smart locks, wifi and cameras for rentals?' Zero acquisition cost."},
   {name:"Property managers -> both, at portfolio scale",note:"One PM relationship can mean washing + cleanup across many properties AND rental-ready tech (locks/wifi/cameras) on every door. Land the PM once; sell both businesses into the whole portfolio."},
   {name:"Jamieson lighting <- OBX seasonal",note:"OBX Lot Solutions sells seasonal/holiday lighting; Jamieson installs the high-ticket PERMANENT app-controlled LED systems. Same customer, two price points."}];
  h+=feeds.map(f=>`<div class="mcard"><div class="mt">${esc(f.name)}</div><div style="font-size:12.5px;margin-top:4px;line-height:1.5">${esc(f.note)}</div></div>`).join("");
  h+=mSect("Adjacent markets that are wide open");
  const adj=[
   {name:"Short-term-rental 'turnover tech + care' bundle",tag:"combines both",note:"Per-door package for vacation rentals: smart lock + wifi + cameras (Jamieson) + exterior wash + home watch + turnover-ready checks (OBX). One price, one vendor, every door a PM manages. This is the single biggest combined opportunity on the OBX. Context: the US short-term-rental market is ~$72B (2025) heading to ~$125B by 2033; the OBX runs ~60% occupancy (just above the US average), and Vacasa alone (recently bought by Casago) manages ~40,000 units — that is how many doors PMs control."},
   {name:"Pool / hot-tub turnover service",tag:"OBX add-on",note:"Rentals need it on turnover days — recurring, high-frequency, pairs with existing property-care accounts. Low skill, brother-friendly labor."},
   {name:"EV charger installation",tag:"Jamieson",note:"Fast-growing; the low-voltage/networking parts are yours, the line-voltage hookup needs a licensed electrician partner. Premium rentals and homes increasingly want it."},
   {name:"Permanent outdoor LED lighting dealership",tag:"Jamieson high-ticket",note:"Become a dealer for one brand (Trimlight/Jellyfish style). ~$2,200 starter to $25/linear ft installed. Year-round (holiday + accent + security), app-controlled = your wheelhouse."},
   {name:"Local microgreens supply to OBX restaurants",tag:"aeroponics, viable",note:"The one realistic aeroponics path: small high-value grow, sold weekly to local farm-to-table restaurants/grocers. AeroFarms proved microgreens (not lettuce) is where the money is."},
   {name:"Storm prep / board-up & post-storm checks",tag:"OBX seasonal premium",note:"Hurricane-season urgent + premium work; ties directly to home watch (you are already checking the property). High willingness to pay when a storm is coming."},
   {name:"Marine Starlink / boat tech",tag:"Jamieson niche",note:"OBX has lots of boat owners; Starlink maritime + electronics is a niche a local competitor (Pro Starlink Installers) already touches — room for a networking-strong specialist."}];
  h+=adj.map(a=>`<div class="mcard"><div class="mt">${esc(a.name)}<span class="mtag gap">${esc(a.tag)}</span></div><div style="font-size:12.5px;margin-top:4px;line-height:1.5">${esc(a.note)}</div></div>`).join("");
  h+=`<div class="card"><div class="msrc">These are strategic syntheses of the per-business research in the other tabs; revisit each tab for the sourced market data behind them.</div></div>`;
  return h;
}
function mColumns(vals,labels){
  const max=Math.max.apply(null,vals)||1,W=330,H=120,n=vals.length,gap=4,bw=(W-gap*(n-1))/n;
  let bars="";vals.forEach((v,i)=>{const bh=Math.max(2,Math.round(v/max*(H-24)));const x=i*(bw+gap),y=H-bh-16;bars+=`<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="2" fill="var(--accent)"></rect><text x="${x+bw/2}" y="${H-4}" font-size="7" text-anchor="middle" fill="var(--muted)">${esc(labels[i])}</text>`;});
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="margin:6px 0">${bars}</svg>`;
}
