function mPlan(key){
  const p=PLANS[key];if(!p)return `<div class="empty" style="padding:16px">No plan yet.</div>`;
  let h=`<div class="card" style="border-left:5px solid var(--accent)"><div class="nm" style="font-size:16px">${esc(p.title)}</div><div class="sub">${esc(p.subtitle)}</div></div>`;
  const tgt=(p.compare&&p.compare[1])?p.compare[1].n:"";
  h+=`<div class="tldr"><div class="t"><div class="v">${esc(tgt)}</div><div class="k">12-month target</div></div><div class="t"><div class="v">${p.actions.d30.length}</div><div class="k">moves in 30 days</div></div><div class="t"><div class="v">${p.add.length}</div><div class="k">streams to add</div></div></div>`;
  h+=mCallout("","The one growth lever",p.lever.name);
  h+=mCallout("info","Do this first",p.actions.d30[0].t);
  h+=`<button class="xlink" onclick="mktView('research')">📊 See the market research →</button>`;
  h+=mAcc("1 · Who we are right now",`<div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55">${esc(p.now)}</div>`,true);
  let goal=`<div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55">${esc(p.goal)}</div><div style="margin-top:10px"><strong>Now vs 12-month target</strong>`+mBars(p.compare)+`</div>`;
  h+=mAcc("2 · Where we're going (12-month target)",goal,true);
  h+=mAcc("3 · The customer we're going to win",`<div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55">${esc(p.customer)}</div>`,false);
  let ch=`<div style="margin-bottom:8px"><strong>Rough lead potential by channel</strong>`+mBars(p.channelChart)+`<div class="sub">Illustrative ranking, not a guarantee.</div></div>`+p.channels.map((c,i)=>`<div class="mcard"><div class="mt">${i+1}. ${esc(c.name)}</div><div style="font-size:12.5px;margin-top:4px;line-height:1.5"><div><b>Spend:</b> ${esc(c.spend)}</div><div><b>Expect:</b> ${esc(c.expect)}</div><div><b>Measure:</b> ${esc(c.measure)}</div><div><b>Cut if:</b> ${esc(c.cut)}</div></div></div>`).join("");
  h+=mAcc(`4 · How we'll reach them (${p.channels.length} channels, ranked)`,ch,false);
  h+=mAcc("5 · What we'll charge",`<div style="white-space:pre-wrap;font-size:13.5px;line-height:1.55">${esc(p.pricing)}</div>`,false);
  h+=mAcc(`6 · What we'll add (${p.add.length})`,p.add.map(a=>`<div class="mcard"><div class="mt">${esc(a.stream)}</div><div style="font-size:12.5px;margin-top:4px;line-height:1.5"><div><b>Why:</b> ${esc(a.why)}</div><div><b>Cost to add:</b> ${esc(a.cost)}</div><div><b>Return:</b> ${esc(a.ret)}</div></div></div>`).join(""),false);
  const lv=p.lever;
  h+=mAcc("7 · The growth lever we're pulling",`<div class="mcard"><div class="mt">${esc(lv.name)}</div><div style="font-size:12.5px;margin-top:4px;line-height:1.5"><div><b>Why this one:</b> ${esc(lv.why)}</div><div><b>Investment:</b> ${esc(lv.invest)}</div><div><b>Horizon:</b> ${esc(lv.horizon)}</div><div style="margin-top:4px"><b>First 3 milestones:</b></div>${lv.milestones.map((m,i)=>`<div>${i+1}. ${esc(m)}</div>`).join("")}</div></div>`,false);
  let act=mTimeline()+`<button class="btn acc" onclick="planLoadTodos('${key}')">Load the 30-day actions into my To-Do list</button>`;
  [["d30","First 30 days"],["d60","31-60 days"],["d90","61-90 days"]].forEach(d=>{act+=`<div style="margin-top:10px"><strong>${d[1]}</strong>`+p.actions[d[0]].map(a=>`<div class="li"><div class="grow"><div class="nm" style="font-size:13px">${esc(a.t)}</div><div class="sub">${esc(a.owner)} · ${esc(a.cost)}</div></div></div>`).join("")+`</div>`;});
  h+=mAcc("8 · 30 / 60 / 90-day actions",act,true);
  h+=mAcc(`9 · What we're NOT doing (${p.not.length})`,p.not.map(n=>`<div class="li"><div class="grow" style="font-size:13px">&#9940; ${esc(n)}</div></div>`).join(""),false);
  let nums=`<div style="font-size:13px;margin-bottom:6px">${esc(p.proj.note)}</div><strong>Projected monthly revenue (12 mo)</strong>`+mColumns(p.proj.rev,p.proj.rev.map((_,i)=>"M"+(i+1)));
  const tot=p.proj.rev.reduce((a,b)=>a+b,0),ctot=p.proj.cost.reduce((a,b)=>a+b,0);
  nums+=`<div class="kpi"><div class="k"><div class="kn">${money(tot)}</div><div class="kl">12-mo revenue</div></div><div class="k"><div class="kn">${money(ctot)}</div><div class="kl">12-mo costs</div></div><div class="k"><div class="kn">${money(tot-ctot)}</div><div class="kl">net (pre-tax, whole business)</div></div></div>`;
  h+=mAcc("10 · The numbers (12-month projection)",nums,true);
  if(p.caveat)h+=`<div class="card"><div class="msrc"><b>Honest caveat:</b> ${esc(p.caveat)}</div></div>`;
  return h;
}
window.planLoadTodos=function(key){
  const biz=key==="obx"?"obx":"jam",p=PLANS[key];if(!p)return;
  const bizName=biz==="obx"?"OBX Lot Solutions":"Jamieson Automation";
  if(!confirm("Add the "+p.actions.d30.length+" first-30-day actions to the "+bizName+" To-Do list?"))return;
  let added=0;p.actions.d30.forEach(a=>{const t="[Plan] "+a.t;if(!(S[biz].todos||[]).some(x=>!x.deleted&&x.title===t)){S[biz].todos.push({id:uid(),title:t,priority:"High",due:today(),done:false,notes:"Owner: "+a.owner+" · Cost: "+a.cost,updatedAt:now()});added++;}});
  save();alert(added+" action"+(added===1?"":"s")+" added to the "+bizName+" To-Do list"+(added===0?" (already there)":"")+".");
};
let MARKETSUB="obx",MARKETVIEW="research",MARKETIND="overview";
function rMarket(){
  const subs=[["obx","OBX Lot Solutions"],["jam","Jamieson Automation"],["aero","Aeroponics"],["expansion","Expansion"]];
  let h=`<div class="secthd"><h2>Market &amp; plans</h2></div>`;
  h+=`<div class="subnav" style="flex-wrap:wrap">`+subs.map(s=>`<button class="subbtn ${MARKETSUB===s[0]?"on":""}" onclick="mktSub('${s[0]}')">${s[1]}</button>`).join("")+`</div>`;
  if(MARKETSUB==="expansion"){h+=mExpansion();}
  else{
    h+=`<div class="subnav" style="margin-top:4px"><button class="subbtn ${MARKETVIEW==="research"?"on":""}" onclick="mktView('research')">📊 Research</button><button class="subbtn ${MARKETVIEW==="plan"?"on":""}" onclick="mktView('plan')">🎯 Action plan</button></div>`;
    if(MARKETVIEW==="plan"){h+=mPlan(MARKETSUB);}
    else{
      const r=MARKET[MARKETSUB];
      if(r.industries){
        const inds=[["overview","★ Overview"]].concat(r.industries.map(i=>[i.key,i.name]));
        h+=`<div class="subnav" style="margin-top:4px;flex-wrap:wrap">`+inds.map(i=>`<button class="subbtn ${MARKETIND===i[0]?"on":""}" onclick="mktInd('${i[0]}')">${esc(i[1])}</button>`).join("")+`</div>`;
        if(MARKETIND==="overview"){h+=mReport(r);}
        else{const ind=r.industries.find(x=>x.key===MARKETIND);h+=ind?mIndustry(ind):mReport(r);}
      } else {h+=mReport(r);}
    }
  }
  view.innerHTML=h;view.scrollTop=0;
}
window.mktSub=function(s){MARKETSUB=s;MARKETIND="overview";render();};
window.mktView=function(v){MARKETVIEW=v;render();};
window.mktInd=function(i){MARKETIND=i;render();};

